import{_ as n,C as t,o as s,c as o,E as a,a2 as c}from"./chunks/framework.uPk2SrVb.js";const g=JSON.parse('{"title":"Stricter acceptance, complete coverage? A completion-contract probe","description":"","frontmatter":{"title":"Stricter acceptance, complete coverage? A completion-contract probe","date":"2026-10-29","column":"digital-employee","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"声明完成所需的检查，能否同时约束重复执行和未列出的副作用？","summary":"Nine synthetic controls distinguish stronger assertions from broader coverage: exact named-tool order and declared state predicates retain their own omission boundaries.","sources":["https://arxiv.org/html/2610.32004v1","https://github.com/salesforce-misc/crm-agent-bench/tree/dcd7c2e2253f54395ec3f08fa0c6ba7433c45bd8"],"pageClass":"runtime-v6-article","item_id":"SIG-20261029-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-29-sig-20261029-005-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-10-29-sig-20261029-005.md","filePath":"en/digital-employee/2026-10-29-sig-20261029-005.md","lastUpdated":null}'),d={name:"en/digital-employee/2026-10-29-sig-20261029-005.md"};function l(h,e,p,u,m,b){const r=t("ArticleCover"),i=t("ArticleTableScroll");return s(),o("div",null,[a(r,{image:"/assets/covers/daily-2026-10-29-sig-20261029-005-cover.png",kicker:"Research",title:"Stricter acceptance, complete coverage? A completion-contract probe",summary:"Nine synthetic controls distinguish stronger assertions from broader coverage: exact named-tool order and declared state predicates retain their own omission boundaries.",version:"2026-10-29",languageHref:"/zh/digital-employee/2026-10-29-sig-20261029-005",languageLabel:"中文"}),a(i,{language:"en"}),e[0]||(e[0]=c('<h1 id="stricter-acceptance-complete-coverage-a-completion-contract-probe" tabindex="-1">Stricter acceptance, complete coverage? A completion-contract probe <a class="header-anchor" href="#stricter-acceptance-complete-coverage-a-completion-contract-probe" aria-label="Permalink to &quot;Stricter acceptance, complete coverage? A completion-contract probe&quot;">​</a></h1><p>One checkout and two checkouts can receive the same completion verdict. In an internal experiment, the same grading helpers received two synthetic traces: one checkout with a balance of 155, and two checkouts with a balance of 310. A contract requiring the checkout action and subsequence order, with no balance assertion, accepted both. The verdict described its declared conditions accurately; it did not establish that the business effect occurred once.</p><p>This article uses the nine controls already completed in the same-day Research Object. No new experiment is introduced. Its proposition is narrow: <strong>even a strict completion verdict is bounded by its declared checks.</strong> For digital-employee acceptance, how a check evaluates and which consequences it covers need separate review.</p><h2 id="two-passing-records-different-balances" tabindex="-1">Two passing records, different balances <a class="header-anchor" href="#two-passing-records-different-balances" aria-label="Permalink to &quot;Two passing records, different balances&quot;">​</a></h2><p>CRM-Agent-Bench combines declared action, argument, order, response, final-state and negative checks. Task declarations determine which checks apply. Its authors report a duplicate-checkout trace with loyalty state 310 rather than 155, and explicitly identify a false negative in the semantic judge&#39;s contradiction flag. That is an author-reported result, not our independent replay of the original trace. <a href="https://arxiv.org/html/2610.32004v1" target="_blank" rel="noreferrer">Paper, sections 2.2–2.3 and Appendix D</a></p><p>Our internal probe supplied synthetic traces, states and assertions directly to the pinned grading and state-validation pure helpers. It ran under Python 3.12.9 without a live business environment or a model judge. The synthetic balance is an experimental field that distinguishes effects; it is not the original paper&#39;s task record. All nine cases matched their predefined expectations. The central controls were:</p><table tabindex="0"><thead><tr><th>Synthetic trace and asserted condition</th><th>Observed verdict</th><th>What the verdict establishes</th></tr></thead><tbody><tr><td>One checkout; subsequence contract, no balance assertion</td><td>Pass</td><td>Required action and relative order exist</td></tr><tr><td>Two checkouts; same sparse contract</td><td>Pass</td><td>This contract does not exclude the duplicate</td></tr><tr><td>Two checkouts; exact named-tool order</td><td>Reject</td><td>The extra named checkout enters the comparison</td></tr><tr><td>Two checkouts; expected balance 155</td><td>Reject</td><td>Actual balance 310 violates declared state</td></tr></tbody></table><p>Adding the relevant assertion distinguishes these synthetic outcomes. This says nothing about the rate of duplicate transactions in live systems, or whether every benchmark task omits the same checks. The implementation identity is the <a href="https://github.com/salesforce-misc/crm-agent-bench/blob/dcd7c2e2253f54395ec3f08fa0c6ba7433c45bd8/src/harness/grading.py" target="_blank" rel="noreferrer">pinned grading source</a>.</p><h2 id="exact-order-still-has-a-filter-boundary" tabindex="-1">Exact order still has a filter boundary <a class="header-anchor" href="#exact-order-still-has-a-filter-boundary" aria-label="Permalink to &quot;Exact order still has a filter boundary&quot;">​</a></h2><p>The examined implementation uses multiset containment for action checks. Subsequence order permits interleaving and duplicates. Exact order is stricter, but it first filters the trace to tools named in the contract. Constraining the sequence of named tools and excluding every other tool from the complete trace are different predicates.</p><p>The internal counterexample calls checkout and then an unlisted deletion tool while retaining balance 155. Exact named-tool order and the balance assertion can both pass. Explicitly forbidding the deletion action rejects the attempt. The negative check concerns the attempted call, without requiring it to be treated as a successful business effect. <a href="https://github.com/salesforce-misc/crm-agent-bench/blob/dcd7c2e2253f54395ec3f08fa0c6ba7433c45bd8/src/harness/grading.py" target="_blank" rel="noreferrer">Order and forbidden checks</a></p><p>State checks have a parallel boundary. Forbidding a field from equalling “Deleted” does not require it to remain at its initial “Open” value. A synthetic “Closed” value passes that forbidden-value check; expanding expected state to require “Open” rejects it. An unchanged-state control passes the expanded assertion. These are declared-leaf semantics, not a guarantee that an entire protected record remains unchanged. <a href="https://github.com/salesforce-misc/crm-agent-bench/blob/dcd7c2e2253f54395ec3f08fa0c6ba7433c45bd8/src/harness/tools/state_validation.py" target="_blank" rel="noreferrer">State-validation source</a></p><p>Our interpretation is that assertion strength and coverage are distinct dimensions. Conjoining more declared predicates does not automatically constrain undeclared tools or fields.</p><h2 id="whole-state-comparison-asks-a-different-equivalence-question" tabindex="-1">Whole-state comparison asks a different equivalence question <a class="header-anchor" href="#whole-state-comparison-asks-a-different-equivalence-question" aria-label="Permalink to &quot;Whole-state comparison asks a different equivalence question&quot;">​</a></h2><p>A pinned historical tau-bench evaluator compares the final database hash against one produced by reference actions and checks required output strings. This offers a concrete alternative to sparse state predicates. It can capture state differences omitted from those predicates, but final-state equality alone does not establish the absence of prohibited intermediate attempts. <a href="https://github.com/sierra-research/tau-bench/blob/59a200c6d575d595120f1cb70fea53cef0632f6b/tau_bench/envs/base.py" target="_blank" rel="noreferrer">Historical evaluator</a></p><p>Neither design is universally preferable. Subsequence semantics may intentionally permit unrelated reads and safe retries; whole-state identity may reject legitimate equivalent outcomes. The historical project warns that its tasks are outdated. We did not execute it or compare current rankings. The useful comparison concerns which business invariants acceptance should preserve and which process differences it should permit.</p><p>For governed digital employees, the supported engineering implication is to expose asserted predicates, unasserted scope, action multiplicity and side-effect boundaries alongside completion. Prohibited intermediate attempts and protected final fields need their own stated basis. This is an acceptance-evidence design recommendation, not deployment certification.</p><h2 id="where-the-evidence-stops" tabindex="-1">Where the evidence stops <a class="header-anchor" href="#where-the-evidence-stops" aria-label="Permalink to &quot;Where the evidence stops&quot;">​</a></h2><p>Public source code is the project&#39;s own primary implementation material, not independent validation. The paper&#39;s duplicate checkout is author-reported; the table describes our internal isolated-helper experiment; separating strength from coverage is our interpretation. We have no independent third-party reproduction of this experiment. Another project&#39;s existence does not supply one.</p><p>We did not replay the full benchmark, original trace archive or model judge. The results cannot estimate live failure rates, rank systems or establish transfer across domains. Publication, citation, review and version status establish provenance and traceability rather than general validity. The generated editorial cover illustrates the proposition and is not experimental data.</p><h2 id="how-will-missing-predicates-be-found" tabindex="-1">How will missing predicates be found? <a class="header-anchor" href="#how-will-missing-predicates-be-found" aria-label="Permalink to &quot;How will missing predicates be found?&quot;">​</a></h2><p>The unresolved questions are how contract review can systematically detect omitted protected fields and forbidden intermediate effects, and how safe retries can remain distinguishable from duplicate business effects. These probes show that faithful contract execution can still answer less than its reader assumes. Further evidence needs to address omission discovery itself, rather than adding another completion boolean without a coverage account.</p>',22))])}const v=n(d,[["render",l]]);export{g as __pageData,v as default};
